/**
 * Assistant Markdown → md2chat payload → clipboard or Word.
 *
 * WeChat / WeCom no longer default to "always a long image": a small policy
 * decides whether the reply should go out as text, as ordered text+image
 * segments (WeCom cannot mix them in one paste), or as one long image.
 * Word is generated by the Host half from the same skill pipeline.
 */
import markdown from 'md2chat-core/chat-markdown.js'
import ChatPayload, { type Payload } from 'md2chat-core/chat-payload.js'
import renderers from 'md2chat-core/renderers.js'
import TableImages from 'md2chat-core/table-images.js'
import ChatTargets from 'md2chat-core/chat-targets.js'
import ClipboardImage from 'md2chat-core/clipboard-image.js'

export type { Payload }

/** Served by the Host half (index.js VENDOR_ROUTE); renderers.js resolves vendor scripts against it. */
const VENDOR_ROUTE = '/api/md2chat-share/vendor/'
;(globalThis as { md2chatVendorBase?: string }).md2chatVendorBase = VENDOR_ROUTE

/** Host half's Word endpoint (index.js WORD_ROUTE) and availability probe. */
const WORD_ROUTE = '/api/md2chat-share/word'
const HEALTH_ROUTE = '/api/md2chat-share/health'

/** Word export depends on a local md2chat skill; absent means the target is hidden. */
export async function wordAvailable(): Promise<boolean> {
  try {
    const response = await fetch(HEALTH_ROUTE, { credentials: 'same-origin' })
    const body = await response.json() as { word?: unknown } | null
    return body?.word === true
  } catch {
    return false
  }
}

export const TARGETS = ['wechat', 'wecom', 'image', 'email', 'word'] as const
export type PluginTarget = (typeof TARGETS)[number]

export type CopyMode = 'auto' | 'image' | 'html' | 'docx'
export function copyMode(target: PluginTarget): CopyMode {
  if (target === 'wechat' || target === 'wecom') return 'auto'
  if (target === 'image') return 'image'
  return target === 'email' ? 'html' : 'docx'
}

export type DeliveryMode = 'text' | 'segments' | 'image'
export interface Delivery {
  mode: DeliveryMode
  reason: string
}

/**
 * The same rule as the skill's policy.mjs:
 * text when there is nothing to rasterise; long image when the reply is
 * structured/short; ordered segments for prose with a few blocks.
 */
export function chooseMode(payload: Payload, target: PluginTarget): Delivery {
  const blocks =
    payload.tableCount + payload.codeImages + payload.mathImages + payload.mermaidImages + payload.originalImages
  const characters = payload.plain.replace(/\s+/g, '').length
  if (blocks === 0) return { mode: 'text', reason: '只有文字：直接发文本，保留换行和缩进' }
  if (blocks >= 3) return { mode: 'image', reason: `有 ${blocks} 个图文块，整段做成一张长图更完整` }
  if (characters < 300) return { mode: 'image', reason: '内容较短且含图文块，一张卡片式长图更好读' }
  return {
    mode: 'segments',
    reason: target === 'wecom' ? '企业微信不能混排：按顺序分段发送，文字保持可编辑' : '以文字为主：正文发文字，表格/代码单独发图',
  }
}

const MAX_IMAGE_BYTES = 10 * 1024 * 1024

function blobToDataUrl(blob: Blob): Promise<string> {
  return new Promise((resolve, reject) => {
    const reader = new FileReader()
    reader.onload = () => { resolve(reader.result as string) }
    reader.onerror = () => { reject(new Error('无法读取图片')) }
    reader.readAsDataURL(blob)
  })
}

/** Remote Markdown images become decoded data URLs, as md2chat's editor does for pasted URLs. */
async function ensureImage(asset: { src: string }) {
  let src = asset.src
  if (!/^data:image\/(png|jpe?g|gif|webp|bmp);base64,/i.test(src)) {
    if (!/^https?:\/\//i.test(src)) throw new Error('暂不支持本地或相对路径图片')
    const response = await fetch(src, { credentials: 'omit', referrerPolicy: 'no-referrer', signal: AbortSignal.timeout(12000) })
    if (!response.ok) throw new Error('HTTP ' + response.status)
    const blob = await response.blob()
    if (!blob.type.startsWith('image/')) throw new Error('返回的不是图片')
    if (blob.size > MAX_IMAGE_BYTES) throw new Error('单张图片不能超过 10 MB')
    src = await blobToDataUrl(blob)
  }
  const image = new Image()
  image.src = src
  try { await image.decode() } catch { throw new Error('图片无法解码') }
  if (image.naturalWidth * image.naturalHeight > 20_000_000) throw new Error('图片不能超过 2000 万像素')
  return { src, width: image.naturalWidth, height: image.naturalHeight }
}

/**
 * Convert one reply with md2chat's pipeline.
 * @param source - the assistant reply's Markdown.
 * @returns the ordered chat payload (segments, email segments, preview HTML, counts).
 */
export function convert(source: string): Promise<Payload> {
  return ChatPayload.build(source, {
    markdown,
    renderers,
    renderTable: (header, rows) => TableImages.render(header, rows),
    ensureImage,
    describeImageError: (src, error) => (src.startsWith('data:') ? '内嵌图片' : src) + '：' + error.message,
  })
}

/**
 * Write the email HTML + plain text. The payload may still be converting:
 * ClipboardItem accepts promised blobs, which keeps the click's user
 * activation alive across slow Mermaid/MathJax renders.
 */
export async function copyRich(payload: Promise<Payload>): Promise<number> {
  const adapted = payload.then((p) => {
    const result = ChatTargets.render(p.emailSegments, 'email')
    return { ...result, plain: p.plain }
  })
  adapted.catch(() => {})
  await navigator.clipboard.write([new ClipboardItem({
    'text/html': adapted.then(a => new Blob([a.html], { type: 'text/html' })),
    'text/plain': adapted.then(a => new Blob([a.plain], { type: 'text/plain' })),
  })])
  return (await adapted).imageCount
}

/**
 * Copy text + table/code/math images as one rich HTML payload. WeChat pastes
 * that in one go; WeCom cannot mix them, so it uses the segment panel instead.
 */
export async function copyChatRich(payload: Promise<Payload>): Promise<number> {
  const adapted = payload.then((p) => {
    const result = ChatTargets.render(p.segments, 'wechat')
    return { ...result, plain: p.plain }
  })
  adapted.catch(() => {})
  await navigator.clipboard.write([new ClipboardItem({
    'text/html': adapted.then(a => new Blob([a.html], { type: 'text/html' })),
    'text/plain': adapted.then(a => new Blob([a.plain], { type: 'text/plain' })),
  })])
  return (await adapted).imageCount
}

function pngBlob(src: string): Blob {
  const bytes = atob(src.slice(src.indexOf(',') + 1))
  return new Blob([Uint8Array.from(bytes, c => c.charCodeAt(0))], { type: 'image/png' })
}

/** Copy the reply's chat text (no markup). Promise-wrapped so the click keeps activation. */
export async function copyPlainText(payload: Promise<Payload>): Promise<void> {
  const text = payload.then(p => new Blob([p.plain], { type: 'text/plain' }))
  text.catch(() => {})
  await navigator.clipboard.write([new ClipboardItem({ 'text/plain': text })])
}

/** Copy one already-rendered segment (text or table/code/math image). */
export async function copySegment(segment: Payload['segments'][number]): Promise<void> {
  if (segment.type === 'text') {
    await navigator.clipboard.writeText(segment.text)
    return
  }
  await navigator.clipboard.write([new ClipboardItem({ 'image/png': pngBlob(segment.src) })])
}

/**
 * Render the whole reply as one long image (md2chat lowers the resolution of
 * very long replies rather than splitting them) and copy it as a lone PNG.
 * The PNG is promised inside the click so slow renders keep user activation.
 */
export async function copyLongImage(payload: Promise<Payload>): Promise<void> {
  const png = payload
    .then(p => ClipboardImage.render(p.segments, { fit: true }))
    .then(image => pngBlob(image.src))
  png.catch(() => {})
  await navigator.clipboard.write([new ClipboardItem({ 'image/png': png })])
}

export interface WordResult { path: string; message: string }

/**
 * Ask the Host half to build a real .docx through the md2chat skill pipeline.
 * Conversion runs in Node (headless Chrome), so the reply can be long and the
 * document keeps editable tables.
 */
export async function makeWord(markdownSource: string): Promise<WordResult> {
  const response = await fetch(WORD_ROUTE, {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify({ markdown: markdownSource }),
  })
  const body = await response.json().catch(() => null) as { ok?: boolean; path?: string; message?: string; error?: string } | null
  if (body?.ok !== true || typeof body.path !== 'string') throw new Error(body?.error ?? 'HTTP ' + response.status)
  return { path: body.path, message: body.message ?? `已生成 Word 文档：${body.path}` }
}
